package com.mavric.health.persistence.sqlserver;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real REQUIRED templates, modeled executor/manager: no connected health or durability proof. */
class SqlServerMonitorStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerMonitorStore store=new SqlServerMonitorStore(executor,manager);
 final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<SqlServerContext> contexts=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/public/status");
 SqlServerMonitorStoreTest(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());calls.add(inv.getArgument(0));contexts.add(inv.getArgument(1));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void row(Map<String,Object> row){results.add(new SqlServerExecutor.Result(List.of(List.of(row)),List.of(0)));}
 void probe(){row(Map.of("ready",1));results.add(new SqlServerExecutor.Result(List.of(),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var error=assertThrows(ApiException.class,work::run);assertEquals(500,error.status);assertEquals("DATABASE_ERROR",error.code);assertNull(error.getCause());assertFalse(error.toString().contains("canary"));}
 @Test void statusThreeModesExactFourFieldsImmutableAndContexts(){for(String mode:List.of("OPEN","READ_ONLY","MAINTENANCE")){row(Map.of("mode",mode,"message","","revision",1,"passwordHash","canary"));var out=store.status(request);assertEquals(Map.of("mode",mode,"message","","revision",1,"status",mode.equals("OPEN")?"OPERATIONAL":"RESTRICTED"),out);assertThrows(UnsupportedOperationException.class,out::clear);assertEquals(List.of(),args.getLast());assertEquals(SqlServerContext.Scope.REQUEST,contexts.getLast().scope());}assertEquals(Collections.nCopies(3,SqlServerProcedure.APPLICATION_STATUS),calls);}
 @Test void statusAcceptsTenantAndPlatformButNotMalformedHost(){request.setAttribute("health.tenant",new TenantRef(ID,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));row(Map.of("mode","OPEN","message","synthetic","revision",2));store.status(request);assertEquals(ID,contexts.getLast().tenantId());request.removeAttribute("health.tenant");request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of("SOP"),"a".repeat(64)));row(Map.of("mode","OPEN","message","synthetic","revision",2));store.status(request);assertEquals(ID,contexts.getLast().actorId());request.setAttribute("health.tenant","forged");safe(()->store.status(request));safe(()->store.status(null));assertEquals(2,calls.size());}
 @Test void invalidStatusResultsetsColumnsAndExactTypesRollback(){for(String key:List.of("mode","message","revision"))for(Object value:Arrays.asList(null,true,0L)){var row=new LinkedHashMap<String,Object>(Map.of("mode","OPEN","message","x","revision",1));row.put(key,value);row(row);safe(()->store.status(request));assertEquals("rollback",manager.events.getLast());}row(Map.of("mode","INVALID","message","x","revision",1));safe(()->store.status(request));row(Map.of("mode","OPEN","message","x","revision",0));safe(()->store.status(request));results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.status(request));results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));safe(()->store.status(request));}
 @Test void workerContextIgnoresHttpAndSampleHasExactLongMetrics(){var prior=new MockHttpServletRequest("POST","/forged");TraceContext.REQUEST.set(prior);probe();store.sample(ID,Long.MAX_VALUE,0,Long.MAX_VALUE);assertSame(prior,TraceContext.REQUEST.get());assertEquals(List.of(SqlServerProcedure.HEALTH_READY,SqlServerProcedure.HEALTH_SAMPLE),calls);assertEquals(List.of(),args.getFirst());var values=args.getLast();assertEquals(6,values.size());assertEquals(ID,values.get(0));assertEquals("UP",values.get(1));assertTrue(values.get(2) instanceof Long);assertTrue((Long)values.get(2)>=0);assertEquals(Long.MAX_VALUE,values.get(3));assertEquals(0L,values.get(4));assertEquals(Long.MAX_VALUE,values.get(5));for(var c:contexts){assertEquals(new SqlServerContext(null,null,null,null,null,null,null,null,null,SqlServerContext.Scope.WORKER),c);}assertEquals(List.of("begin:0","commit"),manager.events);}
 @Test void invalidMetricsBeforeProbeAndBadReadyNeverWritesSample(){for(String id:Arrays.asList(null,"bad",ID.toUpperCase(Locale.ROOT)))assertEquals(400,assertThrows(ApiException.class,()->store.sample(id,0,0,0)).status);for(int index=0;index<3;index++){long[] m={0,0,0};m[index]=-1;assertEquals(400,assertThrows(ApiException.class,()->store.sample(ID,m[0],m[1],m[2])).status);}verifyNoInteractions(executor);for(Object ready:Arrays.asList(null,0,1L,true,"1")){var row=new LinkedHashMap<String,Object>();row.put("ready",ready);row(row);safe(()->store.sample(ID,0,0,0));}results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.sample(ID,0,0,0));assertFalse(calls.contains(SqlServerProcedure.HEALTH_SAMPLE));}
 @Test void requiredJoinProbeWriteAndCommitErrorsNeverPartialOrRetry(){probe();assertThrows(RuntimeException.class,()->manager.outer(()->{store.sample(ID,0,0,0);assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("synthetic cancellation");}));assertEquals("rollback",manager.events.getLast());row(Map.of("ready",1));results.add(new SqlServerExecutor.Result(List.of(List.of()),List.of()));safe(()->store.sample(ID,0,0,0));probe();manager.failCommit=true;safe(()->store.sample(ID,0,0,0));doThrow(new RuntimeException(new java.sql.SQLException("canary",null,229))).when(executor).execute(any(),any(),any(Object[].class));safe(()->store.sample(ID,0,0,0));verify(executor,times(7)).execute(any(),any(),any(Object[].class));}
 @Test void probeResultsetAndRowCardinalityMustBeExactlyOne(){for(var sets:List.<List<List<Map<String,Object>>>>of(List.of(List.of()),List.of(List.of(Map.of("ready",1),Map.of("ready",1))),List.of(List.of(Map.of("ready",1)),List.of()))){results.add(new SqlServerExecutor.Result(sets,List.of()));safe(()->store.sample(ID,0,0,0));assertEquals("rollback",manager.events.getLast());}assertEquals(Collections.nCopies(3,SqlServerProcedure.HEALTH_READY),calls);}
 @Test void writeSqlFailurePropagatesAndDoesNotRetryOrRecordDown(){doAnswer(inv->{var sp=inv.<SqlServerProcedure>getArgument(0);calls.add(sp);if(sp==SqlServerProcedure.HEALTH_READY)return new SqlServerExecutor.Result(List.of(List.of(Map.of("ready",1))),List.of());throw new RuntimeException(new java.sql.SQLException("canary driver",null,51003));}).when(executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->store.sample(ID,1,1,1));assertEquals(409,error.status);assertFalse(error.toString().contains("canary"));assertEquals(List.of(SqlServerProcedure.HEALTH_READY,SqlServerProcedure.HEALTH_SAMPLE),calls);assertEquals("rollback",manager.events.getLast());}

}
